"""Generate review-only HTML from shared CSV; no application dependencies."""
import csv, html
from pathlib import Path
P=Path(__file__).parent
rows=list(csv.DictReader((P.parent/'strings/core.csv').open(encoding='utf-8')))
D={r['key']:r for r in rows}
css='''@font-face{font-family:Arabic;src:url(fonts/NotoSansArabic.ttf);font-weight:100 900}[lang=ar] body{font-family:Arabic,Arial,sans-serif}*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172b45;font:20px/1.5 "DejaVu Sans",Arial,sans-serif}header{height:100px;background:white;border-bottom:1px solid #d9e2ef;display:flex;align-items:center;justify-content:space-between;padding:0 64px}.brand{font-size:27px;font-weight:750;letter-spacing:-1px;display:flex;align-items:center;gap:12px}.logo{background:#0b72d9;border-radius:10px;color:white;width:40px;height:40px;display:grid;place-items:center;font-size:24px}button,.button,select{font:inherit;font-weight:650;border:1px solid #a8bad0;border-radius:10px;min-height:52px;padding:10px 23px;cursor:pointer;background:white;color:#193c62;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:12px}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #0b72d9;outline-offset:4px}.primary{background:#0b72d9;border-color:#0b72d9;color:white}.danger{background:#b42335;border-color:#b42335;color:white}.quiet{border:0;background:transparent;padding:0;min-height:48px;color:#285178}.language{display:flex;gap:14px;align-items:center;font-size:17px}main{max-width:1100px;margin:30px auto}h1{font-size:38px;line-height:1.25;letter-spacing:-1px;margin:0 0 12px}h2{font-size:25px;line-height:1.35;margin:0 0 13px}p{margin:0 0 18px}.muted{color:#52667c}.eyebrow{text-transform:uppercase;letter-spacing:2px;color:#52667c;font-size:14px;font-weight:700;margin-bottom:14px}.cards{display:grid;grid-template-columns:1fr 1fr;gap:26px;margin-top:36px}.card{background:white;border:1px solid #d0ddec;border-radius:20px;padding:32px;box-shadow:0 6px 20px #17345405}.choice{padding:34px;min-height:308px;display:flex;flex-direction:column;text-align:start;align-items:start;justify-content:flex-start;font-weight:400}.choice h2{font-size:28px;margin-top:22px}.choice p{font-size:19px;color:#52667c;max-width:420px}.choice .icon{background:#e8f2fe;color:#0b72d9;border-radius:14px;padding:8px 18px;font-size:27px}.choice .go{color:#0b72d9;font-size:18px;font-weight:700;margin-top:auto}.foot{margin-top:24px;display:flex;justify-content:space-between;align-items:center;font-size:17px;color:#52667c}.privacy{display:flex;align-items:center;gap:9px}.dot{background:#18724a;width:9px;height:9px;border-radius:50%;display:inline-block}.pill{display:inline-block;background:#e5f4eb;color:#175d3c;padding:7px 14px;border-radius:99px;font-weight:650;font-size:16px}.heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}.share-grid{display:grid;grid-template-columns:1.35fr 1fr;gap:24px}.label{font-size:17px;color:#52667c;margin-bottom:8px}.digits{direction:ltr;unicode-bidi:isolate;display:block;font-family:"DejaVu Sans Mono",monospace;font-weight:700;font-size:43px;letter-spacing:1px;color:#113a66;white-space:nowrap}.code{color:#0b72d9;font-size:40px}.value-row{display:flex;align-items:center;justify-content:space-between;gap:15px}.value-row button{font-size:15px;padding:8px 14px;min-height:48px}.divider{border:0;border-top:1px solid #dde6f0;margin:18px 0}.timer{font-size:16px;margin:14px 0 10px;color:#395672}.timerbar{height:5px;border-radius:5px;background:#e3ecf7;margin-bottom:15px}.timerbar span{display:block;width:71%;height:100%;background:#0b72d9;border-radius:5px}.note{font-size:17px;line-height:1.6}.small{font-size:15px}.status-box{background:#eef5fd;border-radius:12px;padding:20px;margin:20px 0}.stop{width:100%;margin-top:15px}.formwrap{max-width:720px;margin:12px auto}.formwrap h1{font-size:34px}.field{display:block;font-size:18px;font-weight:650;margin-top:20px}.field input{font:25px "DejaVu Sans Mono",monospace;display:block;width:100%;min-height:60px;padding:13px 17px;border:1px solid #8ea4bd;border-radius:9px;background:#fff;color:#172b45;margin:8px 0}.field input::placeholder{color:#687f98;opacity:1}.hint{font-size:16px;color:#52667c;margin:6px 0 18px}.wide{width:100%;margin-top:5px}.crumb{font-size:16px;margin-bottom:18px;display:inline-block;color:#285178}.warning{background:#fff5e6;border:1px solid #e0bd82;border-radius:12px;padding:20px;font-size:17px;color:#654214}.warning h2{font-size:20px;color:#654214}.dialog{max-width:750px;margin:30px auto;padding:36px}.dialog h1{font-size:32px}.dialog p{font-size:19px}.dialog .actions{display:flex;justify-content:flex-end;gap:16px;margin-top:25px}.review-label{font-size:14px;color:#52667c;margin-top:16px}.web-layout{display:grid;grid-template-columns:1fr .8fr;gap:48px;align-items:center}.web-layout .card{padding:28px}.web-intro h1{font-size:40px}.step{display:flex;gap:15px;margin:22px 0;font-size:18px}.step span{border-radius:50%;background:#e0edfc;color:#0b72d9;min-width:34px;height:34px;text-align:center;font-weight:700}.web-layout .field{margin-top:10px}.web-layout .hint{margin-bottom:12px}a{color:#075fb7}[dir=rtl] .brand{letter-spacing:0}[dir=rtl] h1{letter-spacing:0}[dir=rtl] .choice{min-height:330px}[dir=rtl] .choice p{font-size:21px}'''
def t(key,lang='cs'):return html.escape(D[key][lang])
def button(key,cl='',lang='cs'):return '<button class="'+cl+'">'+t(key,lang)+'</button>'
def shell(name,body,lang='cs'):
 native={'cs':'Čeština','de':'Deutsch','ar':'العربية'}[lang]
 doc=f'''<!doctype html><html lang="{lang}" dir="{'rtl' if lang=='ar' else 'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>DeskShare — {name}</title><style>{css}</style></head><body><header><div class="brand" dir="ltr"><span class="logo" aria-hidden="true"><svg width="28" height="28" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="4" y="5" width="24" height="17" rx="2"/><path d="M16 22v5m-7 0h14"/></svg></span>DeskShare</div><div class="language"><label for="lang">{t('language.label',lang)}</label><select id="lang" aria-label="{t('language.label',lang)}"><option>{native}</option></select></div></header><main>{body}</main></body></html>'''
 (P/f'{name}.html').write_text(doc,encoding='utf-8')
 return name
names=[]
for lang in ['cs','de','ar']:
 b=f'<div class="eyebrow">DeskShare</div><h1>{t("home.title",lang)}</h1><div class="cards">'
 for role,icon in [('need','<svg width="28" height="28" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="4" y="5" width="24" height="17" rx="2"/><path d="M16 22v5m-7 0h14"/></svg>'),('give','<svg width="28" height="28" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M7 25L25 7M8 7h17v17"/></svg>')]:
  b+=f'<button class="card choice"><span class="icon" aria-hidden="true">{icon}</span><h2>{t("home."+role,lang)}</h2><p>{t("home."+role+"_hint",lang)}</p><span class="go">{t("home."+role,lang)}</span></button>'
 b+=f'</div><div class="foot"><span class="privacy"><i class="dot"></i>{t("share.private",lang)}</span>{button("advanced.label","quiet",lang)}</div>'
 names.append(shell('home-'+lang,b,lang))
b='''<a class="crumb" href="home-cs.html">← Zpět na úvod</a><div class="heading"><div><h1>Sdílíte obrazovku</h1><p class="muted">Vaše číslo a kód řekněte člověku, se kterým jste domluvení.</p></div><span class="pill">● Připojený 1 člověk</span></div><div class="share-grid"><section class="card"><div class="label">Vaše číslo</div><div class="value-row"><bdi class="digits" dir="ltr">609 374 915</bdi><button>Kopírovat</button></div><hr class="divider"><div class="label">Kód</div><div class="value-row"><bdi class="digits code" dir="ltr">VY8–5L5–6RW</bdi><button>Kopírovat</button></div><div class="timer">Nový kód za 32 s</div><div class="timerbar" aria-hidden="true"><span></span></div><p class="note muted">Když se kód změní, přečtěte nový.<br>Vaše číslo zůstává stejné.</p><p class="small muted">Čtěte po jednotlivých znacích, ve třech skupinách.</p></section><section class="card"><h2>Co druhý člověk může?</h2><div class="status-box"><strong>Vidí vaši obrazovku.</strong><p class="note" style="margin:8px 0 0">Ovládání není povoleno. Myš a klávesnici ovládáte jen vy.</p></div><p class="note muted">O ovládání vás může požádat. Rozhodnete se vy.</p><button class="danger stop">Zastavit sdílení</button><p class="small muted" style="margin-top:12px">Okamžitě odpojíte všechny a přestanete sdílet.</p></section></div><div class="foot"><span>Pomoc máte pod kontrolou.</span><button class="quiet">Rozšířené</button></div>'''
names.append(shell('sharing-cs','<style>main{margin:20px auto}.share-grid .card{padding:24px}.heading{margin-bottom:16px}.share-grid .note{margin-bottom:12px}</style>'+b))
form='''<label class="field">Číslo druhého člověka<input dir="ltr" inputmode="numeric" placeholder="123 456 789" autocomplete="off"></label><p class="hint">Druhý člověk ho najde pod „Vaše číslo“.</p><label class="field">Kód<input dir="ltr" placeholder="ABC–234–XYZ" spellcheck="false" autocomplete="off"></label><p class="hint">Kód je na stejné obrazovce. Mezery a pomlčky nevadí.</p><button class="primary wide">Připojit se</button>'''
b='<div class="formwrap"><a class="crumb" href="home-cs.html">← Zpět na úvod</a><h1>Chci pomoct někomu</h1><p class="muted">Požádejte druhého člověka o jeho číslo a kód.</p><section class="card">'+form+'</section><div class="foot"><span>Nejdřív uvidíte obrazovku.<br>O ovládání požádáte zvlášť.</span><button class="quiet">Rozšířené</button></div></div>'
names.append(shell('connect-cs',b))
b='''<div class="eyebrow">Žádost během sdílení</div><section class="card dialog" role="dialog" aria-modal="true" aria-labelledby="title"><span class="pill">Sdílíte obrazovku · ovládání není povoleno</span><h1 id="title" style="margin-top:22px">Povolit ovládání?</h1><p>Druhý člověk chce používat vaši myš a klávesnici. Povolte to jen člověku, kterého znáte a od kterého čekáte pomoc.</p><div class="warning"><h2>Nečekaný hovor? Nic nesdílejte.</h2><p style="font-size:17px;margin:0">Zavěste a zavolejte známému člověku nebo firmě na ověřené číslo. Neukazujte bankovnictví ani nesdělujte hesla.</p></div><p class="note muted" style="margin-top:20px">Ovládání můžete kdykoli zastavit. Zavřením tohoto okna žádost odmítnete.</p><div class="actions"><button style="border:2px solid #193c62">Nepovolit</button><button class="primary">Povolit ovládání</button></div></section><p class="review-label" style="text-align:center">Návrh dialogu · bezpečná výchozí volba: Nepovolit</p>'''
names.append(shell('approval-cs',b))
b='''<div class="web-layout"><section class="web-intro"><div class="eyebrow">Pomoc přes prohlížeč</div><h1>Chci pomoct někomu</h1><p class="muted">Připojte se k obrazovce druhého člověka.<br>Vy nemusíte nic instalovat.</p><div class="step"><span>1</span>Požádejte ho, aby v aplikaci DeskShare<br>zvolil „Potřebuji pomoc“.</div><div class="step"><span>2</span>Zadejte jeho číslo a kód.</div><div class="step"><span>3</span>Uvidíte jeho obrazovku. O ovládání<br>můžete požádat až potom.</div><p class="note" style="margin-top:30px">Potřebujete pomoc vy?<br><a href="#download">Stáhnout aplikaci DeskShare</a></p></section><section class="card"><h2>Připojení</h2>'''+form+'''<p class="small muted" style="margin-top:18px;margin-bottom:0">Připojujte se jen po domluvě s druhým člověkem.</p></section></div><div class="foot"><span>DeskShare · pomoc bez účtu</span><button class="quiet">Rozšířené</button></div>'''
names.append(shell('web-start-cs',b))
(P/'index.html').write_text('<!doctype html><html lang="cs"><meta charset="utf-8"><title>DeskShare: makety</title><style>body{font:20px sans-serif;max-width:900px;margin:40px auto}li{margin:20px}a{color:#0b72d9}</style><h1>DeskShare: statické návrhy</h1><p>1280 × 800. Ukázkové údaje, nefunkční ovládání; sestaveno ze společné tabulky překladů.</p><ul>'+''.join(f'<li><a href="{n}.html">{n} · HTML</a> / <a href="{n}.png">PNG</a></li>' for n in names)+'</ul></html>',encoding='utf-8')
print('\n'.join(names))
